static void HoleOperations(){var shapes=new[]{"Circle","Arc","Sector","Ellipse","Triangle","Rectangle","Diamond","Parallelogram","Pentagon","Hexagon","Polygon"};var d=new CosmicDesignerDocument();foreach(var shape in shapes){var cut=d.AddHole(shape,10+d.Cuts.Count,20);if(cut.Geometry.Count==0||d.InnerContours.All(c=>c.Id!=cut.Id))Fail($"{shape} hole");if(shape!="Circle"&&cut.Geometry.OfType<LineSegment>().Any(l=>l.X1==l.X2&&l.Y1==l.Y2))Fail($"{shape} zero segment");}if(d.Cuts.Count!=11)Fail("hole count");var polygon=d.Cuts.Last();d.UpdateCut(polygon,30,40,8,6,9);if(polygon.Geometry.Count!=9||polygon.CenterX!=30||polygon.CenterY!=40)Fail("editable polygon");}
static void BoundaryCuts(){var d=new CosmicDesignerDocument();var cut=d.AddHole("Rectangle",10,290);d.UpdateCut(cut,10,290,20,20,7);if(!d.CanMergeBoundaryCut(cut)||d.OuterContour.Segments.Count!=4||d.Cuts.Count!=1)Fail("boundary candidate must remain editable");var history=new UndoRedoManager();history.Record(d);if(!d.TryMergeBoundaryCut(cut)||d.Cuts.Count!=0||d.InnerContours.Count!=0||d.OuterContour.Segments.Count!=6)Fail("corner boundary rectangle merge");var undo=history.Undo(d)??throw new InvalidOperationException();if(undo.Cuts.Count!=1||undo.OuterContour.Segments.Count!=4)Fail("boundary merge undo");foreach(var p in new[]{(290d,290d),(290d,10d),(10d,10d)}){var next=d.AddHole("Rectangle",p.Item1,p.Item2);d.UpdateCut(next,p.Item1,p.Item2,20,20,7);if(!d.CanMergeBoundaryCut(next)||!d.TryMergeBoundaryCut(next))Fail("sequential corner boundary merge");}if(d.OuterContour.Segments.Count!=12)Fail("four corner notches");var path=Path.Combine(Path.GetTempPath(),$"boundary-{Guid.NewGuid():N}.dxf");try{CosmicDxfSerializer.Save(d,path);var restored=CosmicDxfSerializer.Load(path);if(restored.OuterContour.Segments.Count!=12||restored.Cuts.Count!=0||restored.InnerContours.Count!=0)Fail("boundary notch metadata roundtrip");}finally{if(File.Exists(path))File.Delete(path);}var plain=new CosmicDesignerDocument();var edge=new System.Windows.Rect(120,280,40,20);if(!BoundaryCutEngine.TrySubtractRectangle(plain.OuterContour.Segments,edge,out var contour)||contour.Count!=8)Fail("edge boundary rectangle merge");if(BoundaryCutEngine.TrySubtractRectangle(plain.OuterContour.Segments,new(120,120,40,20),out _))Fail("interior rectangle must remain cut");}
